# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: scrape ultimateframedata.com/stats (character attributes: weight, fall speed, jumps,
#          ledge options, out of shield, reflectors) into SmashDb's `char_stats` and
#          `reflector` tables, with typed columns and our char ids.
# Usage: `scrape_stats()` (one GET) or `parse_stats(html)`; synced with `ds data stats`.
# ---------------------------------------------------------------------------
#
# Site notes: context the code doesn't show, as of Nov 2026. Re-check the live page if parsing
# breaks.
#
# How the page is built:
# - One static page (no JS needed): each section is an `<h2>` heading followed by one `<table>`
#   whose first row is `<th>` headers, then one row per character (`Rank` and `% Increase`
#   columns are derivable, so not kept).
# - Character names are the site's display names and vary per section: `Rosalina`,
#   `Rosalina & Luma`, `Rosa (no Luma)`; `DK`; `Dedede`; `P.T. [Squirtle]` and
#   `Pokemon Trainer (Squirtle)`. Echo fighters share a row in Landing (`Marth/Lucina`). See
#   `SITE_CHARACTER`.
# - Variants: a few fighters get several rows in a section (Olimar's grab range per Pikmin,
#   Popo / Nana, Ice Climbers leader / partner, Rosalina without Luma). Stored as extra rows
#   with a `variant`; `Steve (Wood)` is Steve's only ledge row, so it is the main one.
# - Values: `**`, `??`, `?` and `N/A` mean unknown -> null. Grab ranges of tether-like grabs
#   end in `~` (approximate). Ken's first out of shield option reads
#   `5 (flame), 6 (normal)`: the first number is stored.
# - Out of Shield marks some moves in coloured bold (hits only behind / only above / leaves
#   you helpless, per its `Key` column); that colouring is not stored, the move names are.
#
# Decisions:
# - The dodge and roll sections are not stored: `framedata.parquet` already has each
#   character's dodges (from its own page). Dash Turnaround is mostly `??`, so skipped too.
# - A missing section or column fails the whole scrape (nothing is written), so a site change
#   can't leave a half-empty table.
# ---------------------------------------------------------------------------
from __future__ import annotations

import re
from collections.abc import Callable
from dataclasses import dataclass

import polars as pl
from bs4 import BeautifulSoup, Tag

from ds.data.char_icons import char_id_by_name
from ds.data.chars import CharId
from ds.util import http

__all__ = [
    "CHAR_STATS_SCHEMA",
    "REFLECTOR_SCHEMA",
    "SECTIONS",
    "SITE_CHARACTER",
    "SITE_URL",
    "SiteChangedError",
    "StatsPage",
    "parse_stats",
    "scrape_stats",
]

SITE_URL = "https://ultimateframedata.com/stats"
USER_AGENT = "Mozilla/5.0 (compatible; delulu-smash-framedata-scraper)"

# a cell's parsed values, by our column name
Values = dict[str, float | int | str | None]
Parse = Callable[[str], Values]

# site name -> (fighters, variant), for names `char_id_by_name` can't match. A variant of
# None is the fighter's main row. Keyed by the site's name (not char_id, as other site maps
# are) because one fighter has several names here, one per variant.
SITE_CHARACTER: dict[str, tuple[tuple[str, ...], str | None]] = {
    "Rosalina": (("rosalina_and_luma",), None),
    "Rosa (no Luma)": (("rosalina_and_luma",), "no luma"),
    "DK": (("donkey_kong",), None),
    "Dedede": (("king_dedede",), None),
    "Mii Sword Fighter": (("mii_swordfighter",), None),
    "Popo": (("ice_climbers",), None),
    "Nana": (("ice_climbers",), "nana"),
    "Ice Climbers (leader)": (("ice_climbers",), None),
    "Ice Climbers (partner)": (("ice_climbers",), "nana"),
    "Steve (Wood)": (("steve",), None),
    "Pit & Dark Pit": (("pit", "dark_pit"), None),
    **{f"P.T. [{p}]": ((f"pt_{p.lower()}",), None) for p in ("Squirtle", "Ivysaur", "Charizard")},
    **{f"Pokemon Trainer ({p})": ((f"pt_{p.lower()}",), None) for p in ("Squirtle", "Ivysaur", "Charizard")},
    # grab range per Pikmin: red / blue / yellow with no extra Pikmin is the main row
    **{
        f"Olimar ({pikmin}{extra})": (("olimar",), None if (pikmin, extra) == ("r/b/y", "") else f"{pikmin}{extra}")
        for pikmin in ("r/b/y", "white", "purple")
        for extra in ("", " +1", " +2")
    },
}

_NUMBER = re.compile(r"-?\d+(?:\.\d+)?")


def _first_number(cell: str) -> str | None:
    match = _NUMBER.search(cell)
    return match.group() if match else None


def _float(column: str) -> Parse:
    """First number in the cell ('19.4 ~' -> 19.4, '1.5x' -> 1.5, '50%' -> 50.0), or None"""

    def parse(cell: str) -> Values:
        number = _first_number(cell)
        return {column: float(number) if number is not None else None}

    return parse


def _int(column: str) -> Parse:
    """First whole number in the cell ('5 (flame), 6 (normal)' -> 5); '??' -> None"""

    def parse(cell: str) -> Values:
        number = _first_number(cell)
        return {column: int(float(number)) if number is not None else None}

    return parse


def _text(column: str) -> Parse:
    """The cell as text; empty, '?' and 'N/A' -> None"""

    def parse(cell: str) -> Values:
        return {column: None if cell in {"", "?", "??", "???", "N/A"} else cell}

    return parse


def _ledge(prefix: str) -> Parse:
    """'1-26 intangible / 55 total / -22 on shield' -> {prefix}_intangible=26, _total=55,
    _on_shield=-22 (the attack only)
    """

    def parse(cell: str) -> Values:
        values: Values = {}
        for suffix, pattern in [
            ("intangible", r"\d+-(\d+) intangible"),
            ("total", r"(\d+) total"),
            ("on_shield", r"(-?\d+) on shield"),
        ]:
            if suffix == "on_shield" and prefix != "ledge_attack":
                continue  # only the ledge attack can be shielded
            match = re.search(pattern, cell)
            values[f"{prefix}_{suffix}"] = int(match.group(1)) if match else None
        return values

    return parse


def _grade(column: str) -> Parse:
    """'15) F-' (the site's rank, then a letter grade) -> 'F-'; '???' -> None"""

    def parse(cell: str) -> Values:
        match = re.search(r"\)\s*([A-Z][+-]?)$", cell)
        return {column: match.group(1) if match else None}

    return parse


