REFLECTOR_COLUMNS: dict[str, Parse] = {
    "Move": _text("move"),
    "Reflector Active": _text("active_frames"),
    "Hitbox": _text("hitbox_frames"),
    "Damage Mult": _float("damage_mult"),
    "Speed Mult": _float("speed_mult"),
    "Break Threshold": _float("break_threshold_pct"),
    "Lifetime Mult": _float("lifetime_mult"),
    "Notes": _text("notes"),
}

_INT_COLUMNS = {"weight", "hard_landing_frames", "soft_landing_frames", "dash_frames", "pivot_dash_frames"}
_TEXT_COLUMNS = {"ledge_attack_range", "oos_1_moves", "oos_2_moves", "oos_3_moves"}


def _dtype(column: str) -> pl.DataType:
    if column in _TEXT_COLUMNS:
        return pl.String()
    if column in _INT_COLUMNS or column.endswith(("_frames", "_frame", "_intangible", "_total", "_on_shield")):
        return pl.Int16()
    if column.startswith("oos_"):
        return pl.Int16()  # oos_grab, oos_zdrop_front, ...: frames
    return pl.Float64()


def _section_columns(parsers: dict[str, Parse]) -> list[str]:
    return [column for parse in parsers.values() for column in parse("1-1 intangible / 1 total / 1 on shield")]


CHAR_STATS_SCHEMA: dict[str, pl.DataType] = {
    "char_id": pl.String(),
    "variant": pl.String(),
    **{column: _dtype(column) for parsers in SECTIONS.values() for column in _section_columns(parsers)},
}

REFLECTOR_SCHEMA: dict[str, pl.DataType] = {
    "char_id": pl.String(),
    **{
        column: pl.Float64() if column.endswith(("_mult", "_pct")) else pl.String()
        for column in _section_columns(REFLECTOR_COLUMNS)
    },
}


class SiteChangedError(ValueError):
    """The page no longer has a section or column the scraper reads"""


@dataclass(frozen=True)
class StatsPage:
    """What one scrape of /stats gives"""

    char_stats: pl.DataFrame  # one row per fighter (variant null), plus one per variant
    reflector: pl.DataFrame  # one row per reflecting move per fighter
    unmatched: list[str]  # site names that are no fighter, skipped (none expected)


def _fighters(site_name: str) -> tuple[tuple[str, ...], str | None] | None:
    """The fighters and variant a site row is about; None when it names no fighter"""
    if site_name in SITE_CHARACTER:
        return SITE_CHARACTER[site_name]
    if char_id := char_id_by_name(site_name):
        return (char_id,), None
    if "/" in site_name:  # echo fighters sharing a row: 'Marth/Lucina'
        ids = [char_id_by_name(part) for part in site_name.split("/")]
        if all(ids):
            return tuple(i for i in ids if i), None
    return None


def _cell_text(cell: Tag) -> str:
    return " ".join(cell.get_text(" ", strip=True).split())


def _table_rows(soup: BeautifulSoup, heading: str, headers: list[str]) -> list[dict[str, str]]:
    """The rows of the table after <h2>heading</h2>, as {header: text}, or raises"""
    h2 = next((h for h in soup.find_all("h2") if h.get_text(strip=True) == heading), None)
    table = h2.find_next("table") if h2 else None
    if table is None:
        raise SiteChangedError(f"{SITE_URL} has no {heading!r} section")
    rows = table.find_all("tr")
    site_headers = [_cell_text(th) for th in rows[0].find_all("th")]
    missing = [h for h in ["Character", *headers] if h not in site_headers]
    if missing:
        raise SiteChangedError(f"{SITE_URL} {heading!r} has no column {missing} (it has {site_headers})")
    cells = [[_cell_text(td) for td in row.find_all(["td", "th"])] for row in rows[1:]]
    return [dict(zip(site_headers, row, strict=False)) for row in cells if len(row) >= len(site_headers) // 2]


def _parse_row(row: dict[str, str], parsers: dict[str, Parse]) -> Values:
    values: Values = {}
    for header, parse in parsers.items():
        values |= parse(row.get(header, ""))
    return values


def parse_stats(html: str) -> StatsPage:
    """The /stats page's HTML -> its `char_stats` and `reflector` tables"""
    soup = BeautifulSoup(html, "html.parser")
    unmatched: list[str] = []

    stats: dict[tuple[str, str | None], Values] = {(char_id.value, None): {} for char_id in CharId}
    for heading, parsers in SECTIONS.items():
        for row in _table_rows(soup, heading, list(parsers)):
            match = _fighters(row["Character"])
            if match is None:
                unmatched.append(f"{heading}: {row['Character']}")
                continue
            char_ids, variant = match
            values = _parse_row(row, parsers)
            for char_id in char_ids:
                record = stats.setdefault((char_id, variant), {})
                if any(record.get(column) is not None for column in values):
                    raise SiteChangedError(f"{heading!r} has two rows for {char_id} {variant or ''}".strip())
                record |= values

    reflectors: list[Values] = []
    for row in _table_rows(soup, "Reflectors", list(REFLECTOR_COLUMNS)):
        match = _fighters(row["Character"])
        if match is None:
            unmatched.append(f"Reflectors: {row['Character']}")
            continue
        values = _parse_row(row, REFLECTOR_COLUMNS)
        reflectors.extend({"char_id": char_id, **values} for char_id in match[0])

    char_stats = pl.DataFrame(
        [{"char_id": char_id, "variant": variant, **values} for (char_id, variant), values in stats.items()],
        schema=CHAR_STATS_SCHEMA,
        strict=False,
    ).sort("char_id", "variant", nulls_last=False)
    reflector = pl.DataFrame(reflectors, schema=REFLECTOR_SCHEMA, strict=False).sort("char_id", "move")
    return StatsPage(char_stats=char_stats, reflector=reflector, unmatched=unmatched)


def scrape_stats() -> StatsPage:
    """GET ultimateframedata.com/stats (one request, not cached) and parse it"""
    with http.request(
        "GET", SITE_URL, source="framedata", name="stats", headers={"User-Agent": USER_AGENT}, follow_redirects=True
    ) as (resp, _):
        resp.raise_for_status()
    return parse_stats(resp.text)
